    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.font = '16px Arial';

    let initialAngle = 30; // radians
    let angle = 0;
    let velocity = 0;
    let gravity = 0.39; // m/s^2
    let damping = 0.9;

    canvas.addEventListener('mousedown', (e) => {
      initialAngle = e.targetTouches[0].pageY / canvas.offsetHeight * Math.PI;
    });

    document.getElementById('release-button').addEventListener('click', () => {
      angle = initialAngle;
      velocity = 0;
    });

    function update() {
      velocity += gravity * Math.sin(angle);
      angle += velocity;
      velocity *= damping;

      if (Math.abs(velocity) < 0.1) {
        velocity = 0;
      }

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.moveTo(canvas.width / 2, canvas.height - 20);
      ctx.lineTo(canvas.width / 2 + Math.cos(angle) * 150, canvas.height - 20 - Math.sin(angle) * 150);
      ctx.stroke();
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText('Angle: ' + Math.round(angle * 180 / Math.PI) + '°', 10, 10);
      ctx.fillText('Velocity: ' + Math.round(velocity * 3.6) + ' m/s', 10, 30);

      requestAnimationFrame(update);
    }

    function simulation() {
      initialAngle = document.getElementById('initial-angle').value * Math.PI / 180;
      requestAnimationFrame(update);
    }

    simulation();
  </script>
</body>
</html>
